import { createRequire } from "node:module";
import { createServer } from "node:http";
import { readFile, stat } from "node:fs/promises";
import { join, extname } from "node:path";

const repo = "/home/ubuntu/.t3/worktrees/surveybeat-next/t3-c354501d-b07008ca06213de5";
const require = createRequire(`${repo}/infra/package.json`);
const { chromium } = require("@playwright/test");
const dist = join(repo, "apps/web/dist");

const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".svg": "image/svg+xml" };

const server = createServer(async (req, res) => {
  const path = new URL(req.url, "http://x").pathname;
  let file = path === "/a" ? "a/index.html" : path === "/de/a" ? "de/a/index.html" : path.slice(1);
  if (file.endsWith("/")) file += "index.html";
  try {
    const full = join(dist, file);
    await stat(full);
    res.writeHead(200, { "content-type": types[extname(full)] ?? "application/octet-stream" });
    res.end(await readFile(full));
  } catch {
    res.writeHead(404);
    res.end("nf");
  }
});
await new Promise((r) => server.listen(4179, r));
const base = "http://localhost:4179";

const ctx = (labels) => ({
  roundId: "round-test-123",
  pulseName: "Weekly Pulse",
  minimumGroupSize: 4,
  aiProcessing: false,
  questions: [
    {
      id: "q-rating-1",
      position: 1,
      text: "How was your week?",
      type: { _tag: "Rating", ...labels, comment: true },
    },
  ],
  actions: [],
  closeTime: 9999999,
  state: "open",
  hasAnswered: false,
});

const browser = await chromium.launch();
const results = [];
const check = (name, ok, detail = "") => results.push(`${ok ? "PASS" : "FAIL"} ${name} ${detail}`);

try {
  // 1. Long anchor labels at 390 px: labels as text, no horizontal overflow.
  for (const [name, labels] of [
    ["short", { lowLabel: "Low", highLabel: "High" }],
    [
      "long",
      {
        lowLabel: "Nicht zu bewältigen und noch ein sehr langes Wort Donaudampfschifffahrtsgesellschaft",
        highLabel: "Sehr gut zu bewältigen, wirklich sehr gut zu bewältigen",
      },
    ],
    ["missing", {}],
  ]) {
    const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
    await page.route("**/exchange", (route) =>
      route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(ctx(labels)) }),
    );
    await page.goto(`${base}/a#t=tok&v=3`);
    await page.waitForSelector("#save:not([disabled])", { timeout: 15000 });
    const texts = await page.locator(".scale label span").allTextContents();
    const sw = await page.evaluate(() => document.documentElement.scrollWidth);
    const labelOverflow = await page.evaluate(() =>
      [...document.querySelectorAll(".scale label")].map((l) => l.scrollWidth <= l.clientWidth + 1),
    );
    check(`${name}: scale texts`, JSON.stringify(texts) !== "", JSON.stringify(texts));
    check(`${name}: scrollWidth <= 390`, sw <= 390, `scrollWidth=${sw}`);
    check(`${name}: labels not clipped`, labelOverflow.every(Boolean), JSON.stringify(labelOverflow));
    const h = await page.evaluate(() => {
      const b = document.querySelector(".scale label")?.getBoundingClientRect();
      return b ? b.height : -1;
    });
    if (name === "long") {
      await page.screenshot({ path: join(process.env.SCRATCH ?? "/tmp", "long-390.png"), fullPage: true });
    }
    check(`${name}: first label height >= 44`, h >= 44, `h=${h}`);
    await page.close();
  }

  // 2. No token: error shown, form hidden.
  {
    const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
    await page.goto(`${base}/a`);
    await page.waitForTimeout(500);
    const errVisible = await page.locator("#err").isVisible();
    const s1Visible = await page.locator("#screen-1").isVisible();
    check("no token: error visible", errVisible);
    check("no token: screen-1 hidden", !s1Visible);
    await page.close();
  }

  // 3. Failed exchange (404): error shown, form hidden.
  {
    const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
    await page.route("**/exchange", (route) => route.fulfill({ status: 404, body: "{}" }));
    await page.goto(`${base}/a#t=expired`);
    await page.waitForTimeout(800);
    check("404 exchange: error visible", await page.locator("#err").isVisible());
    check("404 exchange: screen-1 hidden", !(await page.locator("#screen-1").isVisible()));
    await page.close();
  }

  // 4. German page: labels.
  {
    const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
    await page.route("**/exchange", (route) =>
      route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify(ctx({ lowLabel: "Nicht sicher", highLabel: "Völlig sicher" })),
      }),
    );
    await page.goto(`${base}/de/a#t=tok&v=2`);
    await page.waitForSelector("#save:not([disabled])", { timeout: 15000 });
    const texts = await page.locator(".scale label span").allTextContents();
    check("de: scale texts", JSON.stringify(texts) === JSON.stringify(["1 · Nicht sicher", "2", "3", "4", "5 · Völlig sicher"]), JSON.stringify(texts));
    await page.close();
  }
} finally {
  await browser.close();
  server.close();
}

